insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
select t.id,v.code,v.name,v.description,v.seq,'active'
from (values
('ง 1.1','CAREER-P6-01','อภิปรายแนวทางในการทำงานและปรับปรุงการทำงานแต่ละขั้นตอน','วางแผนและปรับปรุงงานแต่ละขั้นตอน โดยใช้ทักษะการจัดการและการทำงานร่วมกัน',1),
('ง 1.1','CAREER-P6-02','ใช้ทักษะการจัดการในการทำงานและมีทักษะการทำงานร่วมกัน','วางแผน แบ่งหน้าที่ ประสานงาน และประเมินผลการทำงานร่วมกัน',2),
('ง 1.1','CAREER-P6-03','ปฏิบัติตนอย่างมีมารยาทในการทำงานกับครอบครัวและผู้อื่น','สื่อสารสุภาพ แบ่งปัน ใช้ของร่วมกัน และเคารพลำดับการใช้สิ่งของ',3),
('ง 2.1','CAREER-P6-04','สำรวจตนเองเพื่อวางแผนในการเลือกอาชีพ','สำรวจความสนใจ ความสามารถ บุคลิกภาพ และคุณธรรมที่เกี่ยวข้องกับอาชีพ',4),
('ง 2.1','CAREER-P6-05','ระบุความรู้ความสามารถและคุณธรรมที่สัมพันธ์กับอาชีพที่สนใจ','เชื่อมโยงความรู้ ความสามารถ และคุณธรรมกับลักษณะงานในอาชีพที่สนใจ',5),
('ง 1.1','CAREER-M1-01','วิเคราะห์ขั้นตอนการทำงานตามกระบวนการทำงาน','วิเคราะห์บทบาท เป้าหมาย วางแผน แบ่งงาน ปฏิบัติ ประเมินและปรับปรุงงาน',1),
('ง 1.1','CAREER-M1-02','ใช้กระบวนการกลุ่มในการทำงานด้วยความเสียสละ','ร่วมมือและรับผิดชอบบทบาทเพื่อให้งานกลุ่มสำเร็จ',2),
('ง 1.1','CAREER-M1-03','ตัดสินใจแก้ปัญหาการทำงานอย่างมีเหตุผล','วิเคราะห์ปัญหา พิจารณาทางเลือก และตัดสินใจตามขั้นตอน',3),
('ง 2.1','CAREER-M1-04','อธิบายแนวทางการเลือกอาชีพ','พิจารณาคุณธรรม จริยธรรม เจตคติ และข้อมูลอาชีพในการเลือกอาชีพ',4),
('ง 2.1','CAREER-M1-05','มีเจตคติที่ดีต่อการประกอบอาชีพ','เห็นคุณค่าของการประกอบอาชีพสุจริตและอาชีพในชุมชน',5),
('ง 2.1','CAREER-M1-06','เห็นความสำคัญของการสร้างอาชีพ','อธิบายประโยชน์ของการสร้างอาชีพต่อบุคคลและชุมชน',6),
('ง 1.1','CAREER-M2-01','ใช้ทักษะการแสวงหาความรู้เพื่อพัฒนาการทำงาน','ศึกษาค้นคว้า รวบรวม สังเกต สำรวจ และบันทึกข้อมูลเพื่อนำมาพัฒนางาน',1),
('ง 1.1','CAREER-M2-02','ใช้ทักษะกระบวนการแก้ปัญหาในการทำงาน','ระบุปัญหา วิเคราะห์สาเหตุ เลือกแนวทาง และประเมินผลการแก้ปัญหา',2),
('ง 1.1','CAREER-M2-03','มีจิตสำนึกในการทำงานและใช้ทรัพยากรในการปฏิบัติงานอย่างประหยัดและคุ้มค่า','ทำงานอย่างรับผิดชอบและใช้พลังงาน วัสดุ และทรัพยากรอย่างคุ้มค่า',3),
('ง 2.1','CAREER-M2-04','อธิบายการเสริมสร้างประสบการณ์อาชีพ','อธิบายการเรียนรู้และประสบการณ์ที่ช่วยเตรียมความพร้อมสู่อาชีพ',4),
('ง 2.1','CAREER-M2-05','ระบุการเตรียมตัวเข้าสู่อาชีพ','ระบุความรู้ ทักษะ และประสบการณ์ที่จำเป็นสำหรับอาชีพที่สนใจ',5),
('ง 2.1','CAREER-M2-06','มีทักษะพื้นฐานที่จำเป็นสำหรับการประกอบอาชีพที่สนใจ','ฝึกทักษะพื้นฐาน เช่น การทำงาน การแก้ปัญหา การทำงานร่วมกัน การแสวงหาความรู้ และการจัดการ',6),
('ง 1.1','CAREER-M3-01','อภิปรายขั้นตอนการทำงานที่มีประสิทธิภาพ','วิเคราะห์และอธิบายขั้นตอนการทำงานอย่างมีประสิทธิภาพ',1),
('ง 1.1','CAREER-M3-02','ใช้ทักษะในการทำงานร่วมกันอย่างมีคุณธรรม','ร่วมมือ แบ่งหน้าที่ และปฏิบัติต่อผู้อื่นด้วยคุณธรรม',2),
('ง 1.1','CAREER-M3-03','อภิปรายการทำงานโดยใช้ทักษะการจัดการเพื่อการประหยัดพลังงาน ทรัพยากร และสิ่งแวดล้อม','จัดการงานโดยคำนึงถึงการประหยัดพลังงาน ทรัพยากร และผลกระทบต่อสิ่งแวดล้อม',3),
('ง 2.1','CAREER-M3-04','อภิปรายการหางานด้วยวิธีที่หลากหลาย','สำรวจแหล่งข้อมูลและวิธีการหางานที่หลากหลาย',4),
('ง 2.1','CAREER-M3-05','วิเคราะห์แนวทางเข้าสู่อาชีพ','วิเคราะห์คุณสมบัติและเส้นทางการเตรียมตัวเข้าสู่อาชีพ',5),
('ง 2.1','CAREER-M3-06','ประเมินทางเลือกในการประกอบอาชีพที่สอดคล้องกับความรู้ ความถนัดและความสนใจของตนเอง','ประเมินทางเลือกอาชีพโดยเชื่อมโยงความรู้ ความถนัด และความสนใจ',6),
('ง 1.1','CAREER-M46-01','อธิบายวิธีการทำงานเพื่อการดำรงชีวิต','อธิบายวิธีทำงานอย่างมีคุณธรรม ใช้ทักษะการจัดการ แก้ปัญหา และแสวงหาความรู้',1),
('ง 1.1','CAREER-M46-02','สร้างผลงานอย่างมีความคิดสร้างสรรค์และมีทักษะการทำงานร่วมกัน','สร้างผลงานริเริ่มสร้างสรรค์และทำงานร่วมกับผู้อื่น',2),
('ง 1.1','CAREER-M46-03','มีทักษะการจัดการในการทำงาน','วางแผน จัดระบบ ประสานงาน และติดตามการทำงาน',3),
('ง 1.1','CAREER-M46-04','มีทักษะกระบวนการแก้ปัญหาในการทำงาน','วิเคราะห์ปัญหา กำหนดทางเลือก ดำเนินการ และประเมินผล',4),
('ง 1.1','CAREER-M46-05','มีทักษะในการแสวงหาความรู้เพื่อการดำรงชีวิต','ค้นคว้า ตรวจสอบ และประยุกต์ใช้ความรู้เพื่อการดำรงชีวิต',5),
('ง 1.1','CAREER-M46-06','มีคุณธรรมและลักษณะนิสัยในการทำงาน','แสดงความรับผิดชอบ ซื่อสัตย์ ขยัน อดทน และมีวินัยในการทำงาน',6),
('ง 1.1','CAREER-M46-07','ใช้พลังงานและทรัพยากรในการทำงานอย่างคุ้มค่าและยั่งยืนเพื่อการอนุรักษ์สิ่งแวดล้อม','เลือกใช้พลังงานและทรัพยากรอย่างคุ้มค่าและคำนึงถึงความยั่งยืน',7),
('ง 2.1','CAREER-M46-08','อภิปรายแนวทางสู่อาชีพที่สนใจ','วิเคราะห์กลุ่มอาชีพ ลักษณะงาน ความมั่นคง ความก้าวหน้า และการเตรียมตัวเข้าสู่โลกอาชีพ',8),
('ง 2.1','CAREER-M46-09','เลือกและใช้เทคโนโลยีอย่างเหมาะสมกับอาชีพ','เลือกเทคโนโลยีที่เหมาะสมกับลักษณะงานและข้อกำหนดด้านความปลอดภัย',9),
('ง 2.1','CAREER-M46-10','มีประสบการณ์ในอาชีพที่ถนัดและสนใจ','สะสมประสบการณ์จากกิจกรรมหรือโครงงานอาชีพที่สอดคล้องกับความถนัดและความสนใจ',10),
('ง 2.1','CAREER-M46-11','มีคุณลักษณะที่ดีต่ออาชีพ','แสดงความรับผิดชอบ ซื่อสัตย์ ขยัน อดทน และตรงเวลาในการประกอบอาชีพ',11)
) as v(standard_code,code,name,description,seq)
join public.learning_subjects s on s.code='CAREER'
join public.learning_skills sk on sk.subject_id=s.id and sk.code='CAREER'
join public.learning_topics t on t.skill_id=sk.id and t.code=v.standard_code
on conflict(topic_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,updated_at=now();

insert into public.learning_objective_alignments(objective_id,curriculum_id,grade_level_id,sequence_no,required,indicator_classification,notes)
select o.id,c.id,g.id,substring(o.code from '([0-9]+)$')::int,
(o.code in ('CAREER-P6-01','CAREER-P6-02','CAREER-P6-03','CAREER-P6-04','CAREER-M1-01','CAREER-M1-03','CAREER-M2-01','CAREER-M2-02','CAREER-M2-03','CAREER-M3-01','CAREER-M3-02','CAREER-M3-03','CAREER-M3-04','CAREER-M46-01','CAREER-M46-02','CAREER-M46-03','CAREER-M46-04')),
case when o.code in ('CAREER-P6-01','CAREER-P6-02','CAREER-P6-03','CAREER-P6-04','CAREER-M1-01','CAREER-M1-03','CAREER-M2-01','CAREER-M2-02','CAREER-M2-03','CAREER-M3-01','CAREER-M3-02','CAREER-M3-03','CAREER-M3-04','CAREER-M46-01','CAREER-M46-02','CAREER-M46-03','CAREER-M46-04') then 'must_know' else 'should_know' end,
'OBEC 2021 indicator prioritisation; platform alignment to Thai Basic Education Core Curriculum B.E.2551.'
from public.learning_objectives o
join public.learning_curricula c on c.id='a366b931-63be-49b5-8433-dbea2691a055'
cross join lateral (select unnest(case when o.code like 'CAREER-M46-%' then array['M4','M5','M6']::text[] else array[substring(o.code from 'CAREER-(P6|M1|M2|M3)')]::text[] end) grade_code) x
join public.learning_grade_levels g on g.curriculum_id=c.id and g.code=x.grade_code
where o.code like 'CAREER-P6-%' or o.code like 'CAREER-M1-%' or o.code like 'CAREER-M2-%' or o.code like 'CAREER-M3-%' or o.code like 'CAREER-M46-%'
on conflict(objective_id,curriculum_id,grade_level_id) do update set sequence_no=excluded.sequence_no,required=excluded.required,indicator_classification=excluded.indicator_classification,notes=excluded.notes,updated_at=now();